export type MatchLevel = "exact" | "close" | "placeholder";

export interface ProductImage {
  photo: string | null;
  alt: string;
  subject: string;
  match: MatchLevel;
}

const p = (photo: string, subject = "", alt = "", match: MatchLevel = "exact"): ProductImage => ({
  photo,
  subject: subject || "صورة",
  alt: alt || subject || "صورة الصنف",
  match,
});
const none = (subject: string): ProductImage => ({
  photo: null,
  subject,
  alt: "",
  match: "placeholder",
});

